```python
"""Sudoku game logic: board generation, validation and completion checks."""

import random


class SudokuBoard:
    """A 9x9 Sudoku board with puzzle generation and move validation."""

    def __init__(self, clues=36):
        self.grid = [[0] * 9 for _ in range(9)]
        self.solution = None
        self.fixed = [[False] * 9 for _ in range(9)]
        self._generate(clues)

    # ------------------------------------------------------------------ #
    # Generation
    # ------------------------------------------------------------------ #
    def _generate(self, clues):
        self._fill(0)
        self.solution = [row[:] for row in self.grid]
        cells = [(r, c) for r in range(9) for c in range(9)]
        random.shuffle(cells)
        removed = 0
        target = 81 - clues
        for r, c in cells:
            if removed >= target:
                break
            backup = self.grid[r][c]
            self.grid[r][c] = 0
            if self._count_solutions(2) != 1:
                self.grid[r][c] = backup
            else:
                removed += 1
        for r in range(9):
            for c in range(9):
                self.fixed[r][c] = self.grid[r][c] != 0

    def _fill(self, idx):
        if idx == 81:
            return True
        r, c = divmod(idx, 9)
        values = list(range(1, 10))
        random.shuffle(values)
        for v in values:
            if self._fits(self.grid, r, c, v):
                self.grid[r][c] = v
                if self._fill(idx + 1):
                    return True
                self.grid[r][c] = 0
        return False

    # ------------------------------------------------------------------ #
    # Validation helpers
    # ------------------------------------------------------------------ #
    @staticmethod
    def _fits(grid, r, c, v):
        for i in range(9):
            if grid[r][i] == v or grid[i][c] == v:
                return False
        br, bc = 3 * (r // 3), 3 * (c // 3)
        for i in range(br, br + 3):
            for j in range(bc, bc + 3):
                if grid[i][j] == v:
                    return False
        return True

    def conflicts(self, r, c, v):
        """Cells that would clash with value v placed at (r, c)."""
        found = []
        for i in range(9):
            if i != c and self.grid[r][i] == v:
                found.append((r, i))
            if i != r and self.grid[i][c] == v:
                found.append((i, c))
        br, bc = 3 * (r // 3), 3 * (c // 3)
        for i in range(br, br + 3):
            for j in range(bc, bc + 3):
                if (i, j) != (r, c) and self.grid[i][j] == v and (i, j) not in found:
                    found.append((i, j))
        return found

    def mistakes(self):
        """All cells that currently break the Sudoku rules."""
        bad = set()
        for r in range(9):
            seen = {}
            for c in range(9):
                v = self.grid[r][c]
                if v:
                    if v in seen:
                        bad.update(((r, c), (r, seen[v])))
                    else:
                        seen[v] = c
        for c in range(9):
            seen = {}
            for r in range(9):
                v = self.grid[r][c]
                if v:
                    if v in seen:
                        bad.update(((r, c), (seen[v], c)))
                    else:
                        seen[v] = r
        for br in (0, 3, 6):
            for bc in (0, 3, 6):
                seen = {}
                for i in range(3):
                    for j in range(3):
                        pos = (br + i, bc + j)
                        v = self.grid[pos[0]][pos[1]]
                        if v:
                            if v in seen:
                                bad.update((pos, seen[v]))
                            else:
                                seen[v] = pos
        return sorted(bad)

    # ------------------------------------------------------------------ #
    # Moves and completion
    # ------------------------------------------------------------------ #
    def set_cell(self, r, c, v):
        """Place value v (or clear with 0) at (r, c). Returns (ok, message)."""
        if self.fixed[r][c]:
            return False, "Cell ({},{}) is a given clue and cannot be changed.".format(r + 1, c + 1)
        self.grid[r][c] = v
        if v == 0:
            return True, "Cell ({},{}) cleared.".format(r + 1, c + 1)
        clash = self.conflicts(r, c, v)
        if clash:
            spots = ", ".join("({},{})".format(x + 1, y + 1) for x, y in clash)
            return True, "Mistake! {} at ({},{}) clashes with {}.".format(v, r + 1, c + 1, spots)
        return True, "Placed {} at ({},{}).".format(v, r + 1, c + 1)

    def is_complete(self):
        """True when every row, column and 3x3 box holds 1-9 exactly once."""
        target = list(range(1, 10))
        for i in range(9):
            if sorted(self.grid[i]) != target:
                return False
            if sorted(self.grid[r][i] for r in range(9)) != target:
                return False
        for br in (0, 3, 6):
            for bc in (0, 3, 6):
                box = [self.grid[br + i][bc + j] for i in range(3) for j in range(3)]
                if sorted(box) != target:
                    return False
        return True

    # ------------------------------------------------------------------ #
    # Display
    # ------------------------------------------------------------------ #
    def display(self):
        border = "  +-------+-------+-------+"
        lines = ["    1 2 3   4 5 6   7 8 9", border]
        for r in range(9):
            if r in (3, 6):
                lines.append(border)
            cells = [str(self.grid[r][c]) if self.grid[r][c] else "." for c in range(9)]
            row = " ".join(cells)
            row = row[:6] + "| " + row[6:12] + "| " + row[12:]
            lines.append("{} | {} |".format(r + 1, row))
        lines.append(border)
        return "\n".join(lines)
